-- Independent RELEASE access. Prior migration bytes remain unchanged.
CREATE UNIQUE INDEX release_access_owner_binding ON releases(project_id,release_id);
CREATE TABLE release_access_policies(project_id TEXT NOT NULL REFERENCES projects(project_id),gateway_id TEXT NOT NULL,principal_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),created_at TEXT NOT NULL,PRIMARY KEY(project_id,gateway_id)) STRICT;
CREATE TABLE release_access_requests(sequence INTEGER PRIMARY KEY,access_request_id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL,release_id TEXT NOT NULL,dataset_id TEXT NOT NULL REFERENCES preview_write_gates(dataset_id),gateway_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,subject_principal_id TEXT NOT NULL,intent_hash TEXT NOT NULL,request_hash TEXT NOT NULL,request_json TEXT NOT NULL CHECK(json_valid(request_json)),is_write INTEGER NOT NULL CHECK(is_write IN (0,1)),state TEXT NOT NULL CHECK(state IN ('PREPARED','DISPATCHED','UNKNOWN','FINISHED','NOT_SENT')),revision INTEGER NOT NULL CHECK(revision>=0),observation_json TEXT CHECK(observation_json IS NULL OR json_valid(observation_json)),created_at TEXT NOT NULL,dispatched_at TEXT,finished_at TEXT,FOREIGN KEY(project_id,release_id) REFERENCES releases(project_id,release_id),FOREIGN KEY(project_id,dataset_id) REFERENCES datasets(project_id,dataset_id),FOREIGN KEY(project_id,gateway_id) REFERENCES release_access_policies(project_id,gateway_id),CHECK((state IN ('FINISHED','NOT_SENT'))=(finished_at IS NOT NULL)),CHECK((state='PREPARED')=(dispatched_at IS NULL))) STRICT;
CREATE TABLE release_access_request_events(access_request_id TEXT NOT NULL REFERENCES release_access_requests(access_request_id),revision INTEGER NOT NULL,snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),created_at TEXT NOT NULL,PRIMARY KEY(access_request_id,revision)) STRICT;
CREATE INDEX release_access_pending_writes ON release_access_requests(dataset_id,is_write,state);
CREATE INDEX release_access_recovery ON release_access_requests(project_id,gateway_id,state,sequence);
CREATE TRIGGER release_access_policy_update BEFORE UPDATE ON release_access_policies BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_POLICY_IMMUTABLE'); END;
CREATE TRIGGER release_access_policy_delete BEFORE DELETE ON release_access_policies BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_POLICY_IMMUTABLE'); END;
CREATE TRIGGER release_access_request_update BEFORE UPDATE ON release_access_requests WHEN OLD.state IN ('FINISHED','NOT_SENT') OR NEW.access_request_id IS NOT OLD.access_request_id OR NEW.sequence<>OLD.sequence OR NEW.project_id IS NOT OLD.project_id OR NEW.release_id IS NOT OLD.release_id OR NEW.dataset_id IS NOT OLD.dataset_id OR NEW.gateway_id IS NOT OLD.gateway_id OR NEW.configuration_hash IS NOT OLD.configuration_hash OR NEW.subject_principal_id IS NOT OLD.subject_principal_id OR NEW.intent_hash IS NOT OLD.intent_hash OR NEW.request_hash IS NOT OLD.request_hash OR NEW.request_json IS NOT OLD.request_json OR NEW.is_write<>OLD.is_write OR NEW.created_at IS NOT OLD.created_at OR NEW.revision<>OLD.revision+1 OR (OLD.dispatched_at IS NOT NULL AND NEW.dispatched_at IS NOT OLD.dispatched_at) OR NOT ((OLD.state='PREPARED' AND NEW.state='DISPATCHED') OR (OLD.state='DISPATCHED' AND NEW.state IN ('UNKNOWN','FINISHED','NOT_SENT')) OR (OLD.state='UNKNOWN' AND NEW.state IN ('UNKNOWN','FINISHED'))) BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_REQUEST_IMMUTABLE'); END;
CREATE TRIGGER release_access_request_delete BEFORE DELETE ON release_access_requests BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_REQUEST_RETAINED'); END;
CREATE TRIGGER release_access_request_event_update BEFORE UPDATE ON release_access_request_events BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_REQUEST_EVENT_IMMUTABLE'); END;
CREATE TRIGGER release_access_request_event_delete BEFORE DELETE ON release_access_request_events BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_REQUEST_EVENT_IMMUTABLE'); END;
CREATE UNIQUE INDEX release_policy_credential_binding ON release_access_policies(project_id,gateway_id,configuration_hash);
CREATE UNIQUE INDEX release_credential_target_binding ON releases(project_id,release_id,run_id);
CREATE TABLE release_tickets(ticket_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,gateway_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,subject_principal_id TEXT NOT NULL,token_sha256 TEXT NOT NULL UNIQUE,target_json TEXT NOT NULL CHECK(json_valid(target_json)),platform_origin TEXT NOT NULL,release_origin TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('ISSUED','CONSUMED')),session_id TEXT REFERENCES release_sessions(session_id),consumed_at TEXT,audience TEXT NOT NULL CHECK(audience='devmesh.release.ticket.v1'),release_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.releaseId')) STORED NOT NULL,run_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.runId')) STORED NOT NULL,UNIQUE(ticket_id,project_id,gateway_id),FOREIGN KEY(project_id,gateway_id,configuration_hash) REFERENCES release_access_policies(project_id,gateway_id,configuration_hash),FOREIGN KEY(project_id,release_id,run_id) REFERENCES releases(project_id,release_id,run_id),CHECK(json_extract(target_json,'$.projectId') IS project_id),CHECK(json_extract(target_json,'$.purpose') IS 'RELEASE'),CHECK(json_extract(target_json,'$.schemaVersion') IS 'devmesh.release-access-target.v1'),CHECK(platform_origin<>release_origin),CHECK((state='ISSUED' AND session_id IS NULL AND consumed_at IS NULL) OR (state='CONSUMED' AND session_id IS NOT NULL AND consumed_at IS NOT NULL))) STRICT;
CREATE TABLE release_sessions(session_id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL UNIQUE REFERENCES release_tickets(ticket_id),project_id TEXT NOT NULL,gateway_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,subject_principal_id TEXT NOT NULL,token_sha256 TEXT NOT NULL UNIQUE,target_json TEXT NOT NULL CHECK(json_valid(target_json)),platform_origin TEXT NOT NULL,release_origin TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('ACTIVE','REVOKED')),revoked_at TEXT,audience TEXT NOT NULL CHECK(audience='devmesh.release.session.v1'),release_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.releaseId')) STORED NOT NULL,run_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.runId')) STORED NOT NULL,FOREIGN KEY(ticket_id,project_id,gateway_id) REFERENCES release_tickets(ticket_id,project_id,gateway_id),FOREIGN KEY(project_id,gateway_id,configuration_hash) REFERENCES release_access_policies(project_id,gateway_id,configuration_hash),FOREIGN KEY(project_id,release_id,run_id) REFERENCES releases(project_id,release_id,run_id),CHECK(json_extract(target_json,'$.projectId') IS project_id),CHECK(json_extract(target_json,'$.purpose') IS 'RELEASE'),CHECK(json_extract(target_json,'$.schemaVersion') IS 'devmesh.release-access-target.v1'),CHECK((state='ACTIVE' AND revoked_at IS NULL) OR (state='REVOKED' AND revoked_at IS NOT NULL))) STRICT;
CREATE TABLE release_credential_events(kind TEXT NOT NULL CHECK(kind IN ('ticket','session')),credential_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision IN (0,1)),snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),created_at TEXT NOT NULL,ticket_id TEXT GENERATED ALWAYS AS(CASE WHEN kind='ticket' THEN credential_id END) STORED REFERENCES release_tickets(ticket_id),session_id TEXT GENERATED ALWAYS AS(CASE WHEN kind='session' THEN credential_id END) STORED REFERENCES release_sessions(session_id),PRIMARY KEY(kind,credential_id,revision)) STRICT;
CREATE INDEX release_ticket_capacity ON release_tickets(project_id,subject_principal_id,state,expires_at);
CREATE INDEX release_session_capacity ON release_sessions(project_id,subject_principal_id,state,expires_at);
CREATE TRIGGER immutable_release_ticket BEFORE UPDATE ON release_tickets WHEN OLD.state<>'ISSUED' OR NEW.state<>'CONSUMED' OR NEW.session_id IS NULL OR NEW.consumed_at IS NULL OR NEW.ticket_id IS NOT OLD.ticket_id OR NEW.project_id IS NOT OLD.project_id OR NEW.gateway_id IS NOT OLD.gateway_id OR NEW.configuration_hash IS NOT OLD.configuration_hash OR NEW.subject_principal_id IS NOT OLD.subject_principal_id OR NEW.token_sha256 IS NOT OLD.token_sha256 OR NEW.target_json IS NOT OLD.target_json OR NEW.platform_origin IS NOT OLD.platform_origin OR NEW.release_origin IS NOT OLD.release_origin OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at OR NEW.audience IS NOT OLD.audience BEGIN SELECT RAISE(ABORT,'RELEASE_TICKET_IMMUTABLE'); END;
CREATE TRIGGER retained_release_ticket BEFORE DELETE ON release_tickets BEGIN SELECT RAISE(ABORT,'RELEASE_TICKET_RETAINED'); END;
CREATE TRIGGER immutable_release_session BEFORE UPDATE ON release_sessions WHEN OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.revoked_at IS NULL OR NEW.session_id IS NOT OLD.session_id OR NEW.ticket_id IS NOT OLD.ticket_id OR NEW.project_id IS NOT OLD.project_id OR NEW.gateway_id IS NOT OLD.gateway_id OR NEW.configuration_hash IS NOT OLD.configuration_hash OR NEW.subject_principal_id IS NOT OLD.subject_principal_id OR NEW.token_sha256 IS NOT OLD.token_sha256 OR NEW.target_json IS NOT OLD.target_json OR NEW.platform_origin IS NOT OLD.platform_origin OR NEW.release_origin IS NOT OLD.release_origin OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at OR NEW.audience IS NOT OLD.audience BEGIN SELECT RAISE(ABORT,'RELEASE_SESSION_IMMUTABLE'); END;
CREATE TRIGGER retained_release_session BEFORE DELETE ON release_sessions BEGIN SELECT RAISE(ABORT,'RELEASE_SESSION_RETAINED'); END;
CREATE TRIGGER immutable_release_credential_event BEFORE UPDATE ON release_credential_events BEGIN SELECT RAISE(ABORT,'RELEASE_CREDENTIAL_EVENT_IMMUTABLE'); END;
CREATE TRIGGER retained_release_credential_event BEFORE DELETE ON release_credential_events BEGIN SELECT RAISE(ABORT,'RELEASE_CREDENTIAL_EVENT_RETAINED'); END;

CREATE VIEW business_pending_writes AS
 SELECT 'PREVIEW' purpose,access_request_id,project_id,dataset_id FROM preview_access_requests WHERE is_write=1 AND state IN ('DISPATCHED','UNKNOWN')
 UNION ALL SELECT 'RELEASE',access_request_id,project_id,dataset_id FROM release_access_requests WHERE is_write=1 AND state IN ('DISPATCHED','UNKNOWN');
CREATE TRIGGER release_access_request_insert BEFORE INSERT ON release_access_requests WHEN NEW.state<>'PREPARED' OR NEW.revision<>0 OR NEW.dispatched_at IS NOT NULL OR NEW.finished_at IS NOT NULL OR NEW.observation_json IS NOT NULL OR json_extract(NEW.request_json,'$.target.purpose') IS NOT 'RELEASE' OR json_extract(NEW.request_json,'$.target.releaseId') IS NOT NEW.release_id OR json_extract(NEW.request_json,'$.target.projectId') IS NOT NEW.project_id OR json_extract(NEW.request_json,'$.target.datasetId') IS NOT NEW.dataset_id BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_REQUEST_CHANGED'); END;
CREATE TRIGGER release_access_write_dispatch BEFORE UPDATE ON release_access_requests WHEN NEW.state='DISPATCHED' AND NEW.is_write=1 AND NOT EXISTS(
 SELECT 1 FROM preview_write_gates g JOIN release_route_bindings b ON b.project_id=NEW.project_id JOIN projects p ON p.project_id=NEW.project_id JOIN release_publications v ON v.release_id=NEW.release_id JOIN datasets d ON d.dataset_id=g.dataset_id
 WHERE g.dataset_id=NEW.dataset_id AND g.state='OPEN' AND g.fence=json_extract(NEW.request_json,'$.gateFence') AND g.revision=json_extract(NEW.request_json,'$.gateRevision') AND d.state='READY'
 AND p.accepted_release_id=NEW.release_id AND b.release_id=NEW.release_id AND b.route_hash=json_extract(NEW.request_json,'$.target.routeHash') AND b.generation=json_extract(NEW.request_json,'$.target.routeGeneration') AND v.state='PUBLISHED'
) BEGIN SELECT RAISE(ABORT,'RELEASE_ACCESS_GATE_CHANGED'); END;
CREATE TRIGGER release_session_original BEFORE INSERT ON release_sessions WHEN NOT EXISTS(
 SELECT 1 FROM release_tickets t WHERE t.ticket_id=NEW.ticket_id AND t.state='ISSUED' AND t.project_id=NEW.project_id AND t.gateway_id=NEW.gateway_id AND t.configuration_hash=NEW.configuration_hash AND t.subject_principal_id=NEW.subject_principal_id AND t.target_json=NEW.target_json AND t.platform_origin=NEW.platform_origin AND t.release_origin=NEW.release_origin
) BEGIN SELECT RAISE(ABORT,'RELEASE_CREDENTIAL_TARGET_CHANGED'); END;
CREATE TRIGGER release_writes_block_t5 BEFORE INSERT ON acceptance_commits WHEN EXISTS(SELECT 1 FROM business_pending_writes w JOIN releases r ON r.project_id=w.project_id WHERE r.release_id=NEW.release_id) BEGIN SELECT RAISE(ABORT,'ACCEPTANCE_WRITES_UNRESOLVED'); END;
CREATE TRIGGER release_writes_block_publication BEFORE INSERT ON release_publication_proofs WHEN EXISTS(
 SELECT 1 FROM business_pending_writes w JOIN release_promotion_outbox o ON o.release_id=NEW.release_id WHERE w.dataset_id=NEW.target_dataset_id OR w.dataset_id=json_extract(o.request_json,'$.preparation.source.datasetId')
) BEGIN SELECT RAISE(ABORT,'RELEASE_PUBLICATION_WRITES_UNRESOLVED'); END;
CREATE TRIGGER release_writes_block_abort BEFORE INSERT ON acceptance_abort_completions WHEN EXISTS(SELECT 1 FROM business_pending_writes WHERE dataset_id=NEW.source_dataset_id) BEGIN SELECT RAISE(ABORT,'ACCEPTANCE_ABORT_WRITES_UNRESOLVED'); END;
CREATE TRIGGER business_writes_block_open BEFORE UPDATE ON preview_write_gates WHEN NEW.state='OPEN' AND EXISTS(SELECT 1 FROM business_pending_writes WHERE dataset_id=NEW.dataset_id) BEGIN SELECT RAISE(ABORT,'BUSINESS_WRITES_UNRESOLVED'); END;
